(function(){const incoming=[{"id":"social-course-nov12-1","subject":"social","section":"course","topic":"Рынок труда. Безработица","topicOrder":10,"part":1,"cardTitle":"Базовый тест","label":"Базовый тест","title":"Рынок труда. Безработица · Базовый тест","period":"Обществознание","description":"15 заданий. Подсказки, проверка ответов и подробные разборы. Диаграммы — по ссылкам на оригинал.","questions":[{"id":"sc-nov12-1-q1","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/16438f5d-3586-4fa7-bc5d-ee396defc1f7","sourceLabel":"StudyCats · Рынок труда. Безработица · База · вопрос 1","ex":"Полная занятость предполагает отсутствие фрикционной и структурной безработицы. – неверно, полная занятость допускает естественный уровень безработицы, включающий фрикционную и структурную.\n\nПредложение на рынке труда формируют работодатели. – неверно, предложение труда формируют работники (домохозяйства), а работодатели формируют спрос.\n\nФрикционная безработица связана с территориальной, профессиональной мобильностью работников. – верно, она возникает при смене места жительства, профессии, поиске лучших условий.\n\nГосударственные меры обеспечения занятости включают содействие трудоустройству лиц, потерявших работу. – верно, государство реализует программы помощи безработным, биржи труда и т.д.\n\nБезработные не включаются в состав трудоспособного населения и в численность рабочей силы страны. – неверно, безработные входят в состав рабочей силы (экономически активного населения) наряду с занятыми.","type":"multi","q":"Выберите верные суждения о занятости и безработице. Запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Полная занятость предполагает отсутствие фрикционной и структурной безработицы."},{"id":"2","label":"Предложение на рынке труда формируют работодатели."},{"id":"3","label":"Фрикционная безработица связана с территориальной, профессиональной мобильностью работников."},{"id":"4","label":"Государственные меры обеспечения занятости включают содействие трудоустройству лиц, потерявших работу."},{"id":"5","label":"Безработные не включаются в состав трудоспособного населения и в численность рабочей силы страны."}],"answer":["3","4"],"hint":"Оцените каждое утверждение отдельно. Различайте причины безработицы, спрос и предложение труда."},{"id":"sc-nov12-1-q2","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/16438f5d-3586-4fa7-bc5d-ee396defc1f7","sourceLabel":"StudyCats · Рынок труда. Безработица · База · вопрос 2","ex":"циклическая безработица – неверно, она связана с общим экономическим спадом, а здесь проблема в конкретной отрасли – угольной.\n\nфрикционная безработица – неверно, она возникает при временном поиске работы, а здесь рабочие места исчезли навсегда.\n\nсезонная безработица – неверно, добыча угля не является сезонной отраслью.\n\nоткрытая безработица – верно, шахтёры зарегистрировались на бирже труда, официально признаны безработными и активно ищут работу.\n\nструктурная безработица – верно, вызвана изменением структуры спроса на энергоресурсы, что привело к закрытию шахт и исчезновению рабочих мест, требующих переквалификации.\n\nмассовая безработица – верно, так как потеряли работу десятки тысяч человек, что является значительным масштабом.","type":"multi","q":"В стране Z сократились потребление и экспорт угля, большинство шахт закрылось, десятки тысяч шахтёров потеряли работу. Они зарегистрировались на бирже труда и получили статус безработных. Выберите из приведённого ниже списка характеристики возникшей в стране Z безработицы и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"циклическая безработица"},{"id":"2","label":"фрикционная безработица"},{"id":"3","label":"сезонная безработица"},{"id":"4","label":"открытая безработица"},{"id":"5","label":"структурная безработица"},{"id":"6","label":"массовая безработица"}],"answer":["4","5","6"],"hint":"Оцените каждое утверждение отдельно. Различайте причины безработицы, спрос и предложение труда."},{"id":"sc-nov12-1-q3","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/16438f5d-3586-4fa7-bc5d-ee396defc1f7","sourceLabel":"StudyCats · Рынок труда. Безработица · База · вопрос 3","ex":"увеличение ставок налогообложения – неверно, так как рост налогов увеличивает нагрузку на бизнес, снижает стимулы к расширению производства и может привести к сокращению рабочих мест.\n\nмассовая организация курсов профессиональной переподготовки – верно, это помогает безработным приобрести новые профессии, востребованные на рынке труда, снижая структурную безработицу.\n\nповышение размера пособий по безработице – неверно, поскольку высокие пособия могут снизить мотивацию к активному поиску работы и увеличить продолжительность безработицы.\n\nуменьшение экспорта промышленной продукции – неверно, сокращение экспорта ведёт к падению производства и росту безработицы в экспортно-ориентированных отраслях.\n\nсоздание новых рабочих мест в малом бизнесе – верно, развитие малого предпринимательства напрямую увеличивает спрос на рабочую силу и способствует снижению безработицы.\n\nснижение пенсионного возраста – верно, эта мера уменьшает численность экономически активного населения (люди выходят на пенсию раньше), что сокращает предложение труда и статистически снижает уровень безработицы, освобождая рабочие места для молодёжи.","type":"multi","q":"Глава государства поставил перед правительством задачу снижения уровня безработицы в стране. Какие из приведённых мер могут способствовать решению этой задачи? Запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"увеличение ставок налогообложения"},{"id":"2","label":"массовая организация курсов профессиональной переподготовки"},{"id":"3","label":"повышение размера пособий по безработице"},{"id":"4","label":"уменьшение экспорта промышленной продукции"},{"id":"5","label":"создание новых рабочих мест в малом бизнесе"},{"id":"6","label":"снижение пенсионного возраста"}],"answer":["2","5","6"],"hint":"Оцените каждое утверждение отдельно. Различайте причины безработицы, спрос и предложение труда."},{"id":"sc-nov12-1-q4","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/16438f5d-3586-4fa7-bc5d-ee396defc1f7","sourceLabel":"StudyCats · Рынок труда. Безработица · База · вопрос 4","ex":"Безработицей называют социально-экономическое явление, при котором часть трудоспособного населения, желающего трудиться, не может найти себе работу. – верно, это определение.\n\nСезонная безработица характерна для периода экономического кризиса и является следствием спада производства. – неверно, сезонная связана с сезонными колебаниями, а циклическая – с кризисом.\n\nМассовая безработица приводит к снижению уровня жизни большинства населения. – верно, она снижает доходы и потребление.\n\nНевозможность трудоустройства из-за различий в структуре спроса и предложения рабочей силы разной квалификации порождает циклическую безработицу. – неверно, это структурная безработица.\n\nНеосведомлённость безработных о подходящих им вакансиях может быть причиной фрикционной безработицы. – верно, это одна из причин фрикционной безработицы.","type":"multi","q":"Выберите верные суждения о безработице и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Безработицей называют социально-экономическое явление, при котором часть трудоспособного населения, желающего трудиться, не может найти себе работу."},{"id":"2","label":"Сезонная безработица характерна для периода экономического кризиса и является следствием спада производства."},{"id":"3","label":"Массовая безработица приводит к снижению уровня жизни большинства населения."},{"id":"4","label":"Невозможность трудоустройства из-за различий в структуре спроса и предложения рабочей силы разной квалификации порождает циклическую безработицу."},{"id":"5","label":"Неосведомлённость безработных о подходящих им вакансиях может быть причиной фрикционной безработицы."}],"answer":["1","3","5"],"hint":"Оцените каждое утверждение отдельно. Различайте причины безработицы, спрос и предложение труда."},{"id":"sc-nov12-1-q5","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/16438f5d-3586-4fa7-bc5d-ee396defc1f7","sourceLabel":"StudyCats · Рынок труда. Безработица · База · вопрос 5","ex":"Трудовая мотивация каждого десятого работника связана с интересом к порученному делу. - верно, 10% опрошенных придерживаются позиции \"Мне интересно то, чем я занимаюсь\".\n\nДостижение материального благополучия является наиболее популярным мотивом трудовой активности. - верно, 43% опрошенных выбрали такую позицию, как \"Я работаю для того, чтобы обеспечить материальное благополучие себе и своей семье\", что составляет большую долю опрошенных.\n\nМеньшую долю работников мотивирует социальная полезность их деятельности, чем возможность путешествовать, общаться с разными людьми - неверно, большую долю работников мотивирует социальная полезность их деятельности (10%), чем возможность путешествовать, общаться с разными людьми (7% опрошенных).\n\nМеньше всего опрошенных рассматривают карьерный рост в качестве трудовой мотивации. - неверно, меньше всего опрошенных привлекает возможность путешествий, общения с разными людьми (7%) в то время, как за карьеру выступают 13%.\n\nБольше работников думают о реализации своих способностей, чем о карьере. - верно, о реализации своих способностей думают 17% опрошенных, что больше, чем о карьере (13%).","type":"multi","q":"Учёные задавали З0-летним гражданам вопросы: «Зачем Вы работаете, какова Ваша трудовая мотивация?»\nПолученные результаты (в % от числа опрошенных) представлены в виде диаграммы.\n\nНайдите в приведённом списке выводы, которые можно сделать на основе диаграммы, и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Трудовая мотивация каждого десятого работника связана с интересом к порученному делу."},{"id":"2","label":"Достижение материального благополучия является наиболее популярным мотивом трудовой активности."},{"id":"3","label":"Меньшую долю работников мотивирует социальная полезность их деятельности, чем возможность путешествовать, общаться с разными людьми"},{"id":"4","label":"Меньше всего опрошенных рассматривают карьерный рост в качестве трудовой мотивации."},{"id":"5","label":"Больше работников думают о реализации своих способностей, чем о карьере."}],"answer":["1","2","5"],"hint":"Сравнивайте значения на диаграмме, обращая внимание на группы, годы и единицы измерения.","bodyHtml":"<p>Диаграмма к заданию: <a href=\"https://cdn.studycats.ru/o0Oie0k2ClQQ_1.png\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения</a></p><p>Если изображение недоступно, пропустите задание: для ответа нужна диаграмма из источника.</p>"},{"id":"sc-nov12-1-q6","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/16438f5d-3586-4fa7-bc5d-ee396defc1f7","sourceLabel":"StudyCats · Рынок труда. Безработица · База · вопрос 6","ex":"Фрикционная\nНеосведомленность безработных о подходящих им вакансиях\nФакторы, снижающие мобильность рабочей силы\nНесовершенство трудового законодательства\nОсобенности национального характера и образа жизни и т. д.\n\nСтруктурная\nСокращение спроса на работников ряда специальностей из-за внедрения в производство достижений НТР\n\nСезонная\nНекоторые виды деятельности могут осуществляться только в определенные периоды года\n\nЦиклическая\nКризис на товарных рынках влечет массовые увольнения работников предприятий\n\nА) В связи с экономическим кризисом производители промышленных товаров сократили численность персонала. – 4) циклическая безработица, так как она вызвана общим спадом производства, снижением совокупного спроса и деловой активности в экономике, что характерно для фазы рецессии экономического цикла.\nБ) Из-за изменения спроса на энергоресурсы многие шахты закрылись, а шахтёры остались без работы. – 3) структурная безработица, потому что возникает из-за изменения структуры спроса на энергоносители, что делает профессию шахтёра невостребованной и требует переквалификации.\nВ) Выпускники социологического факультета вуза долго ищут работу по специальности, не соглашаясь ни на какую другую. – 1) фрикционная безработица, так как связана с добровольным поиском лучшего места и временем на трудоустройство после окончания учёбы.\nГ) Полгода жители курортного городка обслуживают туристов, а в остальное время большинство из них не работает. – 2) сезонная безработица, поскольку она обусловлена природно-климатическими циклами и сезонным характером работы в туристической отрасли.\nД) Безработные отказываются от предлагаемых вакансий и просят подобрать им более престижную работу. – 1) фрикционная безработица, так как связана с поиском более подходящего места и нежеланием соглашаться на любую работу, что является нормальным процессом на рынке труда.","type":"match","q":"Установите соответствие между примерами и видами безработицы: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца\n\nЗапишите в таблицу выбранные цифры под соответствующими буквами.\n\nПРИМЕРЫ","options":["фрикционная","сезонная","структурная","циклическая"],"rows":[{"id":"row1","label":"В связи с экономическим кризисом производители промышленных товаров сократили численность персонала.","answer":"циклическая"},{"id":"row2","label":"Из-за изменения спроса на энергоресурсы многие шахты закрылись, а шахтёры остались без работы.","answer":"структурная"},{"id":"row3","label":"Выпускники социологического факультета вуза долго ищут работу по специальности, не соглашаясь ни на какую другую.","answer":"фрикционная"},{"id":"row4","label":"Полгода жители курортного городка обслуживают туристов, а в остальное время большинство из них не работает.","answer":"сезонная"},{"id":"row5","label":"Безработные отказываются от предлагаемых вакансий и просят подобрать им более престижную работу","answer":"фрикционная"}],"hint":"Сопоставьте каждый пример с его признаком. Фрикционная безработица связана с поиском работы, структурная — с изменением спроса на профессии, циклическая — с экономическим спадом."},{"id":"sc-nov12-1-q7","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/16438f5d-3586-4fa7-bc5d-ee396defc1f7","sourceLabel":"StudyCats · Рынок труда. Безработица · База · вопрос 7","ex":"Безработицей называют превышение спроса на рабочую силу над её предложением. – неверно, это определение дефицита рабочей силы, а безработица – превышение предложения над спросом.\n\nПо характеру причин различают галопирующую, фрикционную и циклическую безработицу. – неверно, галопирующая – это вид инфляции, а виды безработицы: фрикционная, структурная, циклическая.\n\nФрикционная безработица связана с изменением спроса на труд в отдельных отраслях и регионах вследствие научно-технического прогресса. – неверно, это характеристика структурной безработицы.\n\nЕстественный уровень безработицы – это уровень безработицы при полной занятости, равный количеству незанятых как при фрикционной, так и при структурной безработице. – верно, естественный уровень включает только фрикционную и структурную безработицу.\n\nЦиклическая безработица возникает в период экономического спада. – верно, она связана с сокращением производства и падением совокупного спроса.","type":"multi","q":"Выберите верные суждения о безработице и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Безработицей называют превышение спроса на рабочую силу над её предложением."},{"id":"2","label":"По характеру причин различают галопирующую, фрикционную и циклическую безработицу."},{"id":"3","label":"Фрикционная безработица связана с изменением спроса на труд в отдельных отраслях и регионах вследствие научно-технического прогресса."},{"id":"4","label":"Естественный уровень безработицы — уровень безработицы при полной занятости, включающий фрикционную и структурную безработицу."},{"id":"5","label":"Циклическая безработица возникает в период экономического спада."}],"answer":["4","5"],"hint":"Оцените каждое утверждение отдельно. Различайте причины безработицы, спрос и предложение труда."},{"id":"sc-nov12-1-q8","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/16438f5d-3586-4fa7-bc5d-ee396defc1f7","sourceLabel":"StudyCats · Рынок труда. Безработица · База · вопрос 8","ex":"Состояние рынка труда, при котором часть активного населения принимает решение прекратить трудовую деятельность и больше не работать, называют циклической безработицей. – неверно, это выход из состава рабочей силы, а не безработица; циклическая безработица связана с экономическими циклами.\n\nСпрос на труд на соответствующем рынке имеет производный характер: он зависит от спроса на товар, который производит данный работник. – верно, это ключевая особенность рынка труда: работодатели нанимают работников только тогда, когда есть спрос на их продукцию.\n\nБезработицей называют социально-экономическое явление, суть которого заключается в том, что часть экономически активного населения, желающая трудиться, не может найти работу по специальности или работу вообще. – верно, это классическое определение безработицы.\n\nВ результате высокой безработицы происходит снижение общего уровня жизни населения. – верно, потеря доходов ведёт к сокращению потребления и ухудшению благосостояния.\n\nВозникновение фрикционной безработицы всегда связано с экономическим кризисом и депрессией. – неверно, фрикционная безработица существует даже при полной занятости и связана с естественными процессами поиска работы.","type":"multi","q":"Выберите верные суждения о рынке труда и безработице и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Состояние рынка труда, при котором часть активного населения принимает решение прекратить трудовую деятельность и больше не работать, называют циклической безработицей."},{"id":"2","label":"Спрос на труд на соответствующем рынке имеет производный характер: он зависит от спроса на товар, который производит данный работник."},{"id":"3","label":"Безработицей называют социально-экономическое явление, суть которого заключается в том, что часть экономически активного населения, желающая трудиться, не может найти работу по специальности или работу вообще."},{"id":"4","label":"В результате высокой безработицы происходит снижение общего уровня жизни населения."},{"id":"5","label":"Возникновение фрикционной безработицы всегда связано с экономическим кризисом и депрессией."}],"answer":["2","3","4"],"hint":"Оцените каждое утверждение отдельно. Различайте причины безработицы, спрос и предложение труда."},{"id":"sc-nov12-1-q9","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/16438f5d-3586-4fa7-bc5d-ee396defc1f7","sourceLabel":"StudyCats · Рынок труда. Безработица · База · вопрос 9","ex":"Фрикционная\nНеосведомленность безработных о подходящих им вакансиях\nФакторы, снижающие мобильность рабочей силы\nНесовершенство трудового законодательства\nОсобенности национального характера и образа жизни и т. д.\n\nСтруктурная\nСокращение спроса на работников ряда специальностей из-за внедрения в производство достижений НТР\n\nЦиклическая\nКризис на товарных рынках влечет массовые увольнения работников предприятий\n\nА) Разразившийся в стране экономический кризис привёл к увольнению 30 % работников во всех отраслях промышленности. – 3) циклическая безработица, так как она вызвана общим спадом экономики, охватывающим все отрасли, и связана с фазой рецессии экономического цикла.\nБ) Из-за планового сокращения в связи с переоснащением вооружённых сил были уволены 20 000 военнослужащих «устаревших» специальностей. – 1) структурная безработица, поскольку изменение структуры вооружённых сил и внедрение новых технологий делают некоторые специальности ненужными, требуя переобучения.\nВ) Работник предприятия уволился из-за снижения размера заработной платы и отказался от должности инженера, предложенной ему на бирже труда. – 2) фрикционная безработица, связанная с добровольным уходом в поисках более высокой оплаты и отказом от неподходящих вакансий, что занимает время.\nГ) Хореограф-балетмейстер, работавшая в доме детского творчества, уволилась и уехала в другой город, где не смогла сразу найти работу по специальности. – 2) фрикционная безработица, вызванная территориальной мобильностью: переезд требует времени на поиск нового места работы по специальности.\nД) Выпускники медицинского вуза не согласились работать в городской поликлинике и ищут работу по специальности в платных медицинских центрах. – 2) фрикционная безработица, так как выпускники находятся в процессе поиска работы с лучшими условиями, что является временным периодом адаптации на рынке труда.","type":"match","q":"Установите соответствие между примерами и видами безработицы: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПРИМЕРЫ","options":["структурная","фрикционная","циклическая"],"rows":[{"id":"row1","label":"Разразившийся в стране экономический кризис привёл к увольнению 30 % работников во всех отраслях промышленности","answer":"циклическая"},{"id":"row2","label":"Из-за планового сокращения в связи с переоснащением вооружённых сил были уволены 20 000 военнослужащих «устаревших» специальностей","answer":"структурная"},{"id":"row3","label":"Работник предприятия уволился из-за снижения размера заработной платы и отказался от должности инженера, предложенной ему на бирже труда.","answer":"фрикционная"},{"id":"row4","label":"Хореограф-балетмейстер, работавшая в доме детского творчества, уволилась и уехала в другой город, где не смогла сразу найти работу по специальности.","answer":"фрикционная"},{"id":"row5","label":"Выпускники медицинского вуза не согласились работать в городской поликлинике и ищут работу по специальности в платных медицинских центрах.","answer":"фрикционная"}],"hint":"Сопоставьте каждый пример с его признаком. Фрикционная безработица связана с поиском работы, структурная — с изменением спроса на профессии, циклическая — с экономическим спадом."},{"id":"sc-nov12-1-q10","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/16438f5d-3586-4fa7-bc5d-ee396defc1f7","sourceLabel":"StudyCats · Рынок труда. Безработица · База · вопрос 10","ex":"Спрос на рынке труда формируют работники. – неверно, спрос на труд предъявляют работодатели, а работники формируют предложение труда.\n\nРавновесие на рынке труда устанавливается, когда величина спроса на труд равна величине предложения труда. – верно, это условие равновесия, при котором нет ни дефицита, ни избытка рабочей силы.\n\nК государственным мерам борьбы с безработицей относят поощрение предпринимательской активности граждан, создание новых рабочих мест. – верно, это активные меры политики занятости, направленные на увеличение спроса на труд.\n\nСдельная заработная плата зависит преимущественно от количества отработанного времени. – неверно, сдельная оплата зависит от объёма произведённой продукции, а от времени зависит повременная оплата.\n\nК причинам фрикционной безработицы относят устаревание одних и появление других, ранее не существовавших профессий. – неверно, это причина структурной безработицы, а фрикционная связана с временным поиском работы.","type":"multi","q":"Выберите верные суждения о рынке труда и безработице. Запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Спрос на рынке труда формируют работники."},{"id":"2","label":"Равновесие на рынке труда устанавливается, когда величина спроса на труд равна величине предложения труда."},{"id":"3","label":"К государственным мерам борьбы с безработицей относят поощрение предпринимательской активности граждан, создание новых рабочих мест."},{"id":"4","label":"Сдельная заработная плата зависит преимущественно от количества отработанного времени."},{"id":"5","label":"К причинам фрикционной безработицы относят устаревание одних и появление других, ранее не существовавших профессий."}],"answer":["2","3"],"hint":"Оцените каждое утверждение отдельно. Различайте причины безработицы, спрос и предложение труда."},{"id":"sc-nov12-1-q11","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/16438f5d-3586-4fa7-bc5d-ee396defc1f7","sourceLabel":"StudyCats · Рынок труда. Безработица · База · вопрос 11","ex":"Причины безработицы:\nФрикционная:\n- неосведомленность безработных о подходящих им вакансиях.\n- факторы, снижающие мобильность рабочей силы\n- несовершенство трудового законодательства\n- особенности национального характера и образа жизни и т. д.\n\nСтруктурная:\n- сокращение спроса на работников ряда специальностей из-за внедрения в производство достижений НТР\n\nСезонная:\n- некоторые виды деятельности могут осуществляться только в определенные периоды года\n\nЦиклическая:\n- кризис на товарных рынках влечет массовые увольнения работников предприятий\n\nА) в связи с экономическим кризисом фирмы, производящие различные товары и услуги, сократили численность персонала - 3) циклическая\n\nБ) в службе занятости безработные отказываются от рабочих вакансий и просят подобрать работу менеджеров - 2) фрикционная\n\nВ) ведет к необходимости появления новых профессий - 1) структурная\n\nГ) возникает при первом поиске работы молодёжью - 2) фрикционная\n\nД) выявляет состояние экономической конъюнктуры, отражающей динамику рыночной экономики - 3) циклическая","type":"match","q":"Установите соответствие между признаками и соответствующими им видами безработицы: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\n\nПРИЗНАКИ","options":["структурная","фрикционная","циклическая"],"rows":[{"id":"row1","label":"в связи с экономическим кризисом фирмы, производящие различные товары и услуги, сократили численность персонала","answer":"циклическая"},{"id":"row2","label":"в службе занятости безработные отказываются от рабочих вакансий и просят подобрать работу менеджеров","answer":"фрикционная"},{"id":"row3","label":"ведет к необходимости появления новых профессий","answer":"структурная"},{"id":"row4","label":"возникает при первом поиске работы молодёжью","answer":"фрикционная"},{"id":"row5","label":"выявляет состояние экономической конъюнктуры, отражающей динамику рыночной экономики","answer":"циклическая"}],"hint":"Сопоставьте каждый пример с его признаком. Фрикционная безработица связана с поиском работы, структурная — с изменением спроса на профессии, циклическая — с экономическим спадом."},{"id":"sc-nov12-1-q12","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/16438f5d-3586-4fa7-bc5d-ee396defc1f7","sourceLabel":"StudyCats · Рынок труда. Безработица · База · вопрос 12","ex":"Структурная безработица отражает изменение спроса на устаревшие и новые профессии. – верно, она возникает из-за технологических сдвигов, когда одни профессии исчезают, а другие появляются, и работники не успевают переквалифицироваться.\n\nБезработица выражается в превышении предложения над спросом на рынке труда. – верно, это макроэкономическое определение: количество желающих работать больше числа доступных вакансий.\n\nЦиклическая безработица всегда может быть преодолена работником самостоятельно. – неверно, она связана с общим спадом в экономике и требует государственных мер по стимулированию спроса, а не индивидуальных усилий.\n\nСезонная безработица характерна для экономического кризиса, возникает в результате спада производства. – неверно, сезонная безработица обусловлена природными циклами (например, в сельском хозяйстве или туризме) и не связана с кризисом.\n\nК последствиям безработицы относят снижение дохода домохозяйства, утрату квалификации работников. – верно, длительное отсутствие работы ведёт к падению уровня жизни и потере профессиональных навыков.","type":"multi","q":"Выберите верные суждения о безработице и её видах и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Структурная безработица отражает изменение спроса на устаревшие и новые профессии."},{"id":"2","label":"Безработица выражается в превышении предложения над спросом на рынке труда."},{"id":"3","label":"Циклическая безработица всегда может быть преодолена работником самостоятельно."},{"id":"4","label":"Сезонная безработица характерна для экономического кризиса, возникает в результате спада производства."},{"id":"5","label":"К последствиям безработицы относят снижение дохода домохозяйства, утрату квалификации работников."}],"answer":["1","2","5"],"hint":"Оцените каждое утверждение отдельно. Различайте причины безработицы, спрос и предложение труда."},{"id":"sc-nov12-1-q13","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/16438f5d-3586-4fa7-bc5d-ee396defc1f7","sourceLabel":"StudyCats · Рынок труда. Безработица · База · вопрос 13","ex":"Все термины в списке, кроме двух, непосредственно связаны с функционированием рынка труда - система социально-трудовых отношений, позволяющих работодателю удовлетворять потребность в трудовых услугах, которые работники готовы предоставить в обмен на заработную плату.\n\nработодатель - ключевой субъект, формирующий спрос на труд (объем услуг труда, который фирмы готовы приобрести при существующих ценах на труд), то есть покупает право на использование труда.\n\nпрожиточный минимум - влияет на стоимость рабочей силы и уровень минимальной заработной платы.\n\nповышение квалификации - связано с качеством предложения на рынке труда и человеческим капиталом.\n\nструктурная безработица - один из видов безработицы.\n\nВыпадающие термины:\n\nоблигация - это долговая ценная бумага, которая относится к финансовому рынку, а не к рынку труда.\n\nпотребление - это конечная цель производства, связанная с использованием товаров и услуг для удовлетворения потребностей.","type":"multi","q":"Ниже приведён ряд терминов. Все они, за исключением двух, характеризуют рынок труда. Найдите два термина, «выпадающих» из общего ряда.","options":[{"id":"1","label":"повышение квалификации"},{"id":"2","label":"облигация"},{"id":"3","label":"прожиточный минимум"},{"id":"4","label":"потребление"},{"id":"5","label":"структурная безработица"},{"id":"6","label":"работодатель"}],"answer":["2","4"],"hint":"Оцените каждое утверждение отдельно. Различайте причины безработицы, спрос и предложение труда."},{"id":"sc-nov12-1-q14","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/16438f5d-3586-4fa7-bc5d-ee396defc1f7","sourceLabel":"StudyCats · Рынок труда. Безработица · База · вопрос 14","ex":"структурная безработица – неверно, она связана с изменениями в структуре экономики: исчезают отдельные отрасли и профессии, появляются новые технологии. В условии же спрос упал почти во всех отраслях сразу, а профессии работников остались востребованными.\n\nскрытая безработица – верно, работников не уволили, и формально они считаются занятыми. Но фактически они работают неполное время или вовсе не работают, находясь в неоплачиваемых отпусках. Официально безработными их не признают.\n\nфрикционная безработица – неверно, она носит добровольный и кратковременный характер и связана с поиском более подходящей работы. Здесь работники не ищут новое место: сокращение рабочего времени им навязано обстоятельствами.\n\nциклическая безработица – верно, она вызвана экономическим спадом, то есть фазой экономического цикла, когда падает совокупный спрос и сокращается производство во всех отраслях.\n\nмассовая безработица – верно, проблема затронула несколько сотен тысяч работников сотен предприятий по всей стране, то есть охватила значительную часть рабочей силы.\n\nсезонная безработица – неверно, сокращение рабочего времени связано с экономическим спадом, а не со временем года.","type":"multi","q":"В стране Y начался экономический спад, спрос на товары упал почти во всех отраслях. Сотни предприятий по всей стране не стали увольнять работников, а перевели несколько сотен тысяч человек на неполную рабочую неделю или отправили в неоплачиваемые отпуска. Выберите из приведённого ниже списка характеристики безработицы, возникшей в стране Y, и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"структурная безработица"},{"id":"2","label":"скрытая безработица"},{"id":"3","label":"фрикционная безработица"},{"id":"4","label":"циклическая безработица"},{"id":"5","label":"массовая безработица"},{"id":"6","label":"сезонная безработица"}],"answer":["2","4","5"],"hint":"Оцените каждое утверждение отдельно. Различайте причины безработицы, спрос и предложение труда."},{"id":"sc-nov12-1-q15","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/16438f5d-3586-4fa7-bc5d-ee396defc1f7","sourceLabel":"StudyCats · Рынок труда. Безработица · База · вопрос 15","ex":"Циклическая безработица связана с фазами экономического цикла, особенно с кризисом и спадом, когда сокращается производство и спрос на рабочую силу во всех отраслях\n\nСтруктурная безработица вызвана масштабными изменениями в экономике: исчезновением целых отраслей, появлением новых технологий, что приводит к несоответствию между спросом на труд и квалификацией работников в разрезе отраслей и регионов.\n\nФрикционная безработица является добровольной и кратковременной, она связана с естественным процессом поиска нового, более подходящего места работы при смене профессии, переезде или в поиске более интересной работы.\n\nА) возникает в результате экономического спада (спада производства) - 3) циклическая \nБ) возникает в связи с изменением спроса на труд в отдельных отраслях или территориях - 1) структурная\nВ) вызвана добровольным решением найти более интересное применение профессиональных умений - 2) фрикционная\nГ) вызывается изменениями в структуре спроса и технологии производства - 1) структурная\nД) охватывает все сферы производства - 3) циклическая","type":"match","q":"Установите соответствие между признаками и соответствующими им видами безработицы: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\n\nПРИЗНАКИ","options":["структурная","фрикционная","циклическая"],"rows":[{"id":"row1","label":"возникает в результате экономического спада (спада производства)","answer":"циклическая"},{"id":"row2","label":"возникает в связи с изменением спроса на труд в отдельных отраслях или территориях","answer":"структурная"},{"id":"row3","label":"вызвана добровольным решением найти более интересное применение профессиональных умений","answer":"фрикционная"},{"id":"row4","label":"вызывается изменениями в структуре спроса и технологии производства","answer":"структурная"},{"id":"row5","label":"охватывает все сферы производства","answer":"циклическая"}],"hint":"Сопоставьте каждый пример с его признаком. Фрикционная безработица связана с поиском работы, структурная — с изменением спроса на профессии, циклическая — с экономическим спадом."}]},{"id":"social-course-nov12-2","subject":"social","section":"course","topic":"Рынок труда. Безработица","topicOrder":10,"part":2,"cardTitle":"Углублённый тест","label":"Углублённый тест","title":"Рынок труда. Безработица · Углублённый тест","period":"Обществознание","description":"10 заданий. Подсказки, проверка ответов и подробные разборы. Диаграммы — по ссылкам на оригинал.","questions":[{"id":"sc-nov12-2-q1","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/b8a27fb7-887c-4277-8898-6b0ece1d2397","sourceLabel":"StudyCats · Рынок труда. Безработица · Про · вопрос 1","ex":"Среди 25-летних тех, кто отметил, что безработица в небольших размерах полезна, меньше тех, кто отметил, что безработица вполне допустима. - неверно, среди 25-летних тех, кто отметил, что безработица в небольших размерах полезна, больше (30%) тех, кто отметил, что безработица вполне допустима (20%).\n\nДоля тех, кто затруднился с ответом, среди 50-летних больше, чем среди 25-летних. - неверно, наоборот, доля тех, кто затруднился с ответом, среди 50-летних меньше (5%), чем среди 25-летних(10%).\n\nДоля тех, кто отметил необходимость безработицы для эффективного развития экономики, меньше среди 25-летних, чем среди 50-летних. - верно, доля тех, кто отметил необходимость безработицы для эффективного ведения хозяйства, среди 25-летних - 15%, что меньше, чем среди 50-летних (20%).\n\nДоля тех, кто отметил, что безработица недопустима, среди 50-летних больше, чем среди 25-летних. - верно, доля тех, кто отметил, что безработица недопустима, среди 50-летних составляет 30%, что больше, чем среди 25-летних (25%).\n\nРавные доли 50-летних отметили, что безработица в небольших размерах полезна и что безработица необходима для эффективного развития экономики. - верно, за позицию, что безработица в небольших размерах полезна выступили 20% так же, как и за то, что безработица необходима для эффективного ведения хозяйства (20%).","type":"multi","q":"В ходе социологических опросов 25-летних и 50-летних граждан страны Z им предлагали высказать своё мнение о безработице.\n\nПолученные результаты (в % от числа опрошенных) представлены в виде диаграммы.\n\nНайдите в приведённом списке выводы, которые можно сделать на основе диаграммы, и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Среди 25-летних тех, кто отметил, что безработица в небольших размерах полезна, меньше тех, кто отметил, что безработица вполне допустима."},{"id":"2","label":"Доля тех, кто затруднился с ответом, среди 50-летних больше, чем среди 25-летних."},{"id":"3","label":"Доля тех, кто отметил необходимость безработицы для эффективного развития экономики, меньше среди 25-летних, чем среди 50-летних."},{"id":"4","label":"Доля тех, кто отметил, что безработица недопустима, среди 50-летних больше, чем среди 25-летних."},{"id":"5","label":"Равные доли 50-летних отметили, что безработица в небольших размерах полезна и что безработица необходима для эффективного развития экономики"}],"answer":["3","4","5"],"hint":"Сравнивайте значения на диаграмме, обращая внимание на группы, годы и единицы измерения.","bodyHtml":"<p>Диаграмма к заданию: <a href=\"https://cdn.studycats.ru/iGvDDxcylV2K_soc_37_1.png\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения</a></p><p>Если изображение недоступно, пропустите задание: для ответа нужна диаграмма из источника.</p>"},{"id":"sc-nov12-2-q2","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/b8a27fb7-887c-4277-8898-6b0ece1d2397","sourceLabel":"StudyCats · Рынок труда. Безработица · Про · вопрос 2","ex":"Циклическая безработица связана с фазами экономического цикла, особенно с кризисом и спадом, когда сокращается производство и падает спрос на рабочую силу во всех отраслях.\n\nСтруктурная безработица вызвана масштабными изменениями в экономике: исчезновением целых отраслей и профессий, появлением новых технологий. Из-за этого квалификация работников перестаёт соответствовать спросу на труд в отраслях и регионах.\n\nФрикционная безработица является добровольной и кратковременной. Она связана с естественным процессом поиска нового, более подходящего места работы при смене работы, переезде, первом трудоустройстве или поиске более интересной работы.\n\nА) Учитель обществознания уволился по собственному желанию из школы в связи с переездом в другой город. - 3) фрикционная\nБ) В связи с экономическим кризисом в стране массово теряют работу представители различных профессий. - 1) циклическая\nВ) В связи с появлением персональных компьютеров машинистки остались без работы. - 2) структурная\nГ) Дворник был уволен за регулярные прогулы и в настоящее время пытается найти аналогичную работу в другом районе города. - 3) фрикционная (профессия по-прежнему востребована, человек просто ищет новое место)\nД) Выпускники экономических вузов ищут работу по специальности. - 3) фрикционная","type":"match","q":"Установите соответствие между примерами и соответствующими им видами безработицы: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПРИМЕРЫ","options":["циклическая","структурная","фрикционная"],"rows":[{"id":"row1","label":"Учитель обществознания уволился по собственному желанию из школы в связи с переездом в другой город","answer":"фрикционная"},{"id":"row2","label":"В связи с экономическим кризисом в стране массово теряют работу представители различных профессий.","answer":"циклическая"},{"id":"row3","label":"В связи с появлением персональных компьютеров машинистки остались без работы.","answer":"структурная"},{"id":"row4","label":"Дворник был уволен за регулярные прогулы и в настоящее время пытается найти аналогичную работу в другом районе города.","answer":"фрикционная"},{"id":"row5","label":"Выпускники экономических ВУЗов ищут работу по специальности.","answer":"фрикционная"}],"hint":"Сопоставьте каждый пример с его признаком. Фрикционная безработица связана с поиском работы, структурная — с изменением спроса на профессии, циклическая — с экономическим спадом."},{"id":"sc-nov12-2-q3","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/b8a27fb7-887c-4277-8898-6b0ece1d2397","sourceLabel":"StudyCats · Рынок труда. Безработица · Про · вопрос 3","ex":"Рост безработицы приводит к снижению общего уровня жизни населения. - верно, безработные лишаются заработной платы, сокращаются доходы семей и совокупный спрос, а государство вынуждено тратить больше средств на пособия при уменьшении налоговых поступлений.\n\nСоциальные издержки безработицы связаны с утратой профессионального и человеческого общения, причастности к общему делу. - верно, кроме экономических потерь безработица влечёт социальные и психологические последствия: человек теряет круг общения и ощущение своей нужности, растут стресс, социальная напряжённость и преступность.\n\nФрикционная безработица проявляется в невозможности трудоустройства людей определённых профессий и связана с несоответствием структуры спроса и предложения на рынке труда. - неверно, здесь описана структурная безработица. Фрикционная безработица носит добровольный и кратковременный характер и связана с поиском более подходящей работы.\n\nСтруктурная безработица проявляется в сокращении числа занятых во всех отраслях экономики в условиях экономического спада. - неверно, здесь описана циклическая безработица. Структурная безработица связана с изменениями в структуре экономики: исчезновением отраслей и профессий, появлением новых технологий.\n\nПри безработице часть экономически активного населения, желающая работать, не может найти работу. - верно, именно так определяется безработица: безработными считаются люди, которые хотят работать, активно ищут работу и готовы к ней приступить, но не имеют её.","type":"multi","q":"Выберите верные суждения о безработице. Запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"В результате роста безработицы происходит снижение общего уровня жизни населения."},{"id":"2","label":"Социальные издержки безработицы связаны с утратой профессионального и человеческого общения, причастности к общему делу."},{"id":"3","label":"Фрикционная безработица проявляется в невозможности трудоустройства людей определённых профессий и связана с несоответствием структуры спроса и предложения на рынке труда."},{"id":"4","label":"Структурная безработица проявляется в сокращении числа занятых во всех отраслях экономики в условиях экономического спада."},{"id":"5","label":"При безработице часть экономически активного населения, желающая работать, не может найти работу."}],"answer":["1","2","5"],"hint":"Оцените каждое утверждение отдельно. Различайте причины безработицы, спрос и предложение труда."},{"id":"sc-nov12-2-q4","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/b8a27fb7-887c-4277-8898-6b0ece1d2397","sourceLabel":"StudyCats · Рынок труда. Безработица · Про · вопрос 4","ex":"Трудовые ресурсы - подходит, это часть населения, способная к труду, из которой формируются и занятые, и безработные.\n\nКоммерческий банк - выпадает, это финансовое учреждение, основная деятельность которого - кредитование, расчетные и кассовые операции, работа с депозитами.\n\nРынок труда - подходит, это сфера, где формируется спрос и предложение рабочей силы, и непосредственно возникает безработица.\n\nЗанятость - подходит, это состояние, противоположное безработице, они являются двумя сторонами одного процесса.\n\nФондовая биржа - выпадает, это институт финансового рынка, где совершаются операции с ценными бумагами. Он напрямую не относится к рынку труда и проблеме безработицы.\n\nПособие - подходит, в данном контексте подразумевается пособие по безработице, которое является прямой мерой социальной поддержки безработных.","type":"multi","q":"Ниже приведен ряд терминов. Все они, за исключением двух, относятся к понятию «безработица». Найдите два термина, «выпадающих» из общего ряда, и запишите в ответ цифры, под которыми они указаны.","options":[{"id":"1","label":"Трудовые ресурсы"},{"id":"2","label":"Коммерческий банк"},{"id":"3","label":"Рынок труда"},{"id":"4","label":"Занятость"},{"id":"5","label":"Фондовая биржа"},{"id":"6","label":"Пособие"}],"answer":["2","5"],"hint":"Оцените каждое утверждение отдельно. Различайте причины безработицы, спрос и предложение труда."},{"id":"sc-nov12-2-q5","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/b8a27fb7-887c-4277-8898-6b0ece1d2397","sourceLabel":"StudyCats · Рынок труда. Безработица · Про · вопрос 5","ex":"Циклическая безработица связана с фазами экономического цикла, особенно с кризисом и спадом, когда сокращается производство и спрос на рабочую силу во всех отраслях\n\nСтруктурная безработица вызвана масштабными изменениями в экономике: исчезновением целых отраслей, появлением новых технологий, что приводит к несоответствию между спросом на труд и квалификацией работников в разрезе отраслей и регионов.\n\nФрикционная безработица является добровольной и кратковременной, она связана с естественным процессом поиска нового, более подходящего места работы при смене профессии, переезде или в поиске более интересной работы.\n\nСезонная безработица: некоторые виды деятельности могут осуществляться только в определенные периоды года\n\nА) Металлургический комбинат в связи с экономическим кризисом объявил о сокращении штата сотрудников. - 1) циклическая\n\nБ) После окончания туристического периода часть горничных приморских отелей осталась без работы. - 3) сезонная\n\nВ) Группа выпускников престижного вуза отказывается от низкооплачиваемых вакансий на бирже труда и ждёт предложений работы, которая бы их удовлетворила. - 4) фрикционная\n\nГ) На производстве электроламповых приборов ввели новые технологии, позволившие оптимизировать производство и сократить численность работников отрасли. - 2) структурная\n\nД) Электрогазосварщик вынужден был уволиться из-за переезда в другой город и временно остался без работы. - 4) фрикционная","type":"match","q":"Установите соответствие между примерами и видами безработицы: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПРИМЕРЫ","options":["циклическая","структурная","сезонная","фрикционная"],"rows":[{"id":"row1","label":"Металлургический комбинат в связи с экономическим кризисом объявил о сокращении штата сотрудников.","answer":"циклическая"},{"id":"row2","label":"После окончания туристического периода часть горничных приморских отелей осталась без работы.","answer":"сезонная"},{"id":"row3","label":"Группа выпускников престижного вуза отказывается от низкооплачиваемых вакансий на бирже труда и ждёт предложений работы, которая бы их удовлетворила.","answer":"фрикционная"},{"id":"row4","label":"На производстве электроламповых приборов ввели новые технологии, позволившие оптимизировать производство и сократить численность работников отрасли.","answer":"структурная"},{"id":"row5","label":"Электрогазосварщик вынужден был уволиться из-за переезда в другой город и временно остался без работы.","answer":"фрикционная"}],"hint":"Сопоставьте каждый пример с его признаком. Фрикционная безработица связана с поиском работы, структурная — с изменением спроса на профессии, циклическая — с экономическим спадом."},{"id":"sc-nov12-2-q6","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/b8a27fb7-887c-4277-8898-6b0ece1d2397","sourceLabel":"StudyCats · Рынок труда. Безработица · Про · вопрос 6","ex":"Добровольная - верно, безработица является добровольной, когда люди, имея возможность трудоустройства, отказываются от предлагаемых вакансий (в данном случае не по специальности) и предпочитают продолжать поиск.\n\nОткрытая - верно, так как люди официально признаются безработными (они ищут работу и готовы к ней приступить, но на своих условиях).\n\nЦиклическая - неверно, связана с экономическим спадом и кризисом, когда рабочих мест не хватает в принципе. В данном случае проблема не в отсутствии вакансий, а в нежелании граждан менять специальность. Государство предлагает варианты трудоустройства, но они не востребованы.\n\nСкрытая - неверно, при скрытой безработице люди формально считаются занятыми, но не работают или работают неполный день. В условии же описана ситуация, когда люди официально не трудоустроены и ищут работу, что является признаком открытой безработицы.\n\nФрикционная - верно, так как граждане сознательно затягивают поиск работы, пытаясь найти место именно по своей специальности. Фрикционная безработица связана с добровольным поиском нового места работы, устраивающего работника по его квалификации и запросам.\n\nСезонная - неверно, не упоминается и не следует из условия, нет указаний на то, что поиск работы зависит от времени года.","type":"multi","q":"Граждане страны Z обычно долго ищут работу по специальности, не соглашаясь ни на какую другую. Государственная служба занятости предлагает различные варианты переобучения с последующим трудоустройством, однако эта услуга мало востребована. Выберите в приведённом ниже списке характеристики безработицы в стране Z и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Добровольная"},{"id":"2","label":"Открытая"},{"id":"3","label":"Циклическая"},{"id":"4","label":"Скрытая"},{"id":"5","label":"Фрикционная"},{"id":"6","label":"Сезонная"}],"answer":["1","2","5"],"hint":"Оцените каждое утверждение отдельно. Различайте причины безработицы, спрос и предложение труда."},{"id":"sc-nov12-2-q7","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/b8a27fb7-887c-4277-8898-6b0ece1d2397","sourceLabel":"StudyCats · Рынок труда. Безработица · Про · вопрос 7","ex":"Номинальная - сумма денег, получаемая за труд в течение определенного периода. Например, Авдотья получает 70 тысяч рублей.\n\nРеальная - количество товаров и услуг, которое можно приобрести на номинальную заработную плату. Например, Авдотья получает 70 тысяч рублей: этих денег ей хватает на оплату съемной квартиры, повседневных товаров, покупку одежды.\n\nА)  начисляется работникам за отработанное время - 1)  номинальная\n\nБ)  выражается в материальных благах и услугах - 2)  реальная\n\nВ)  зависит от цен на приобретаемые товары - 2)  реальная\n\nГ)  начисляется работникам за сверхурочные работы - 1)  номинальная\n\nД)  начисляется работникам за определенное количество и качество выполненных работ - 1)  номинальная","type":"match","q":"Установите соответствие между особенностями заработной платы и ее видами: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\n \n\nОСОБЕННОСТИ","options":["номинальная","реальная"],"rows":[{"id":"row1","label":"начисляется работникам за отработанное время","answer":"номинальная"},{"id":"row2","label":"выражается в материальных благах и услугах","answer":"реальная"},{"id":"row3","label":"зависит от цен на приобретаемые товары","answer":"реальная"},{"id":"row4","label":"начисляется работникам за сверхурочные работы","answer":"номинальная"},{"id":"row5","label":"начисляется работникам за определенное количество и качество выполненных работ","answer":"номинальная"}],"hint":"Определите, что описывает каждый пункт: вид заработной платы или доходную и расходную части бюджета."},{"id":"sc-nov12-2-q8","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/b8a27fb7-887c-4277-8898-6b0ece1d2397","sourceLabel":"StudyCats · Рынок труда. Безработица · Про · вопрос 8","ex":"Циклическая безработица связана с фазами экономического цикла, особенно с кризисом и спадом, когда сокращается производство и спрос на рабочую силу во всех отраслях\n\nФрикционная безработица является добровольной и кратковременной, она связана с естественным процессом поиска нового, более подходящего места работы при смене профессии, переезде или в поиске более интересной работы.\n\nA)  связана с поиском работы специалистом, впервые появившимся на рынке труда - 1)  фрикционная\n\nБ)  вызвана добровольным решением найти более интересное применение профессиональных умений - 1)  фрикционная\n\nB)  возникает из-за увольнения работника по собственной воле - 1)  фрикционная\n\nГ)  вызвана экономическим спадом и закрытием предприятий - 2)  циклическая\n\nД)  проявляется в высвобождении части рабочей силы в период депрессии - 2)  циклическая","type":"match","q":"Установите соответствие между особенностями безработицы и ее видами: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\n \n\nОСОБЕННОСТИ БЕЗРАБОТИЦЫ","options":["фрикционная","циклическая"],"rows":[{"id":"row1","label":"связана с поиском работы специалистом, впервые появившемся на рынке труда","answer":"фрикционная"},{"id":"row2","label":"вызвана добровольным решением найти более интересное применение профессиональных умений","answer":"фрикционная"},{"id":"row3","label":"возникает из-за увольнения работника по собственной воле","answer":"фрикционная"},{"id":"row4","label":"вызвана экономическим спадом и закрытием предприятий","answer":"циклическая"},{"id":"row5","label":"проявляется в высвобождении части рабочей силы в период депрессии","answer":"циклическая"}],"hint":"Сопоставьте каждый пример с его признаком. Фрикционная безработица связана с поиском работы, структурная — с изменением спроса на профессии, циклическая — с экономическим спадом."},{"id":"sc-nov12-2-q9","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/b8a27fb7-887c-4277-8898-6b0ece1d2397","sourceLabel":"StudyCats · Рынок труда. Безработица · Про · вопрос 9","ex":"Занятые - неверно, занятые - это люди, которые осуществляют трудовую деятельность или иную деятельность, не противоречащую законодательству РФ и направленную на получение дохода.\n\nТрудоспособные - верно, Надежде 40 лет, что относится к трудоспособному возрасту. Эта категория характеризует потенциал человека для участия в трудовой деятельности, а не его текущий статус.\n\nВременно безработные - неверно, безработный - это тот, кто не имеет работы, но активно ищет её. Надежда работу не ищет.\n\nОтчаявшиеся найти работу - неверно, нет никаких указаний в условии, что Надежда хочет и безуспешно пытается трудоустроиться\n\nНе включаемые в численность рабочей силы - верно, к этой категории относятся люди, которые не работают и не ищут работу. Поскольку Надежда является домохозяйкой и не занимается активным поиском работы на рынке труда, она статистически не включается в численность рабочей силы.\n\nЧастично занятые - неверно, это те, кто работает неполный рабочий день или неполную рабочую неделю по найму. Домашние обязанности не считаются экономической занятостью. Надежда не работает за плату, домашний труд не считается занятостью","type":"multi","q":"Надежде 40 лет, она домохозяйка. Женщина поддерживает порядок в доме, заботится о муже, работающем на крупном предприятии. К каким категориям населения можно отнести Надежду? Выберите из предложенного списка нужные позиции","options":[{"id":"1","label":"Занятые."},{"id":"2","label":"Трудоспособные."},{"id":"3","label":"Временно безработные."},{"id":"4","label":"Отчаявшиеся найти работу."},{"id":"5","label":"Не включаемые в численность рабочей силы."},{"id":"6","label":"Частично занятые."}],"answer":["2","5"],"hint":"Оцените каждое утверждение отдельно. Различайте причины безработицы, спрос и предложение труда."},{"id":"sc-nov12-2-q10","subject":"social","section":"course","topic":"Рынок труда. Безработица","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/b8a27fb7-887c-4277-8898-6b0ece1d2397","sourceLabel":"StudyCats · Рынок труда. Безработица · Про · вопрос 10","ex":"Фрикционная безработица - это временная безработица, связанная с добровольным поиском нового места работы, соответствующего квалификации и ожиданиям человека.\n\nНашедшие работу, но пока не трудоустроенные на ней - верно, находятся в кратком периоде между наймом и началом работы.\n\nУволенные в связи с падением спроса на их услуги - неверно, это структурная безработица (изменения в структуре экономики).\n\nВновь появившиеся на рынке труда и имеющие требуемую квалификацию - верно, это выпускники учебных заведений, которые ищут свое первое место работы.\n\nУволенные в условиях общего спада производства в стране - неверно, это циклическая безработица (кризис в экономике).\n\nЗанятые неполный рабочий день - неверно, эти люди считаются занятыми, а не безработными.\n\nУволившиеся по собственному желанию - верно, находятся в процессе поиска новой работы.","type":"multi","q":"В государстве Z довольно высокий уровень безработицы. Какие категории населения могут быть отнесены к фрикционным безработным? Запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Нашедшие работу, но пока не трудоустроенные на ней."},{"id":"2","label":"Уволенные в связи с падением спроса на их услуги."},{"id":"3","label":"Вновь появившиеся на рынке труда и имеющие требуемую квалификацию."},{"id":"4","label":"Уволенные в условиях общего спада производства в стране."},{"id":"5","label":"Занятые неполный рабочий день."},{"id":"6","label":"Уволившиеся по собственному желанию."}],"answer":["1","3","6"],"hint":"Оцените каждое утверждение отдельно. Различайте причины безработицы, спрос и предложение труда."}]},{"id":"social-course-nov12-3","subject":"social","section":"course","topic":"Домохозяйства и рациональное экономическое поведение","topicOrder":11,"part":1,"cardTitle":"Базовый тест","label":"Базовый тест","title":"Домохозяйства и рациональное экономическое поведение · Базовый тест","period":"Обществознание","description":"15 заданий. Подсказки, проверка ответов и подробные разборы. Диаграммы — по ссылкам на оригинал.","questions":[{"id":"sc-nov12-3-q1","subject":"social","section":"course","topic":"Домохозяйства и рациональное экономическое поведение","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/0814fa89-5a2d-471f-9350-9e08f50c6613","sourceLabel":"StudyCats · Домохозяйства и рациональное экономическое поведение · База · вопрос 1","ex":"заработная плата – доход: Айгуль получает зарплату за работу бухгалтером.\nпроценты по вкладу – доход: банк начисляет проценты на её сбережения, размещённые на депозите.\nвыплата кредита и процентов по нему – не доход, а расход: Айгуль возвращает банку деньги, взятые на покупку автомобиля, и платит проценты.\nкоммунальные платежи – не доход, а расход: это плата за жильё и коммунальные услуги.\nарендная плата за сдачу в наём комнаты – доход: квартиросъёмщик платит Айгуль за пользование комнатой.\nналог на доходы физических лиц – не доход, а обязательный платёж государству, который удерживается из её зарплаты.","type":"multi","q":"Айгуль работает бухгалтером. Часть своих сбережений она разместила на банковском депозите. Комнату в своей квартире она сдала внаём через агентство недвижимости. Айгуль взяла кредит на покупку автомобиля. Что из перечисленного относится к доходам Айгуль? Запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"заработная плата"},{"id":"2","label":"проценты по вкладу"},{"id":"3","label":"выплата кредита и процентов по нему"},{"id":"4","label":"коммунальные платежи"},{"id":"5","label":"арендная плата за сдачу в наём комнаты"},{"id":"6","label":"налог на доходы физических лиц"}],"answer":["1","2","5"],"hint":"Различайте доходы и расходы. Рациональный выбор предполагает сравнение пользы и затрат при ограниченных ресурсах."},{"id":"sc-nov12-3-q2","subject":"social","section":"course","topic":"Домохозяйства и рациональное экономическое поведение","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/0814fa89-5a2d-471f-9350-9e08f50c6613","sourceLabel":"StudyCats · Домохозяйства и рациональное экономическое поведение · База · вопрос 2","ex":"1 — верно: рациональное поведение включает продуманное распределение доходов и расходов.\n2 — верно: рациональный выбор возможен в любой экономической системе. Дефицит и распределение ограничивают доступные варианты, но не исключают сопоставление пользы и затрат.\n3 — неверно: сравнение результатов и затрат является признаком рационального поведения.\n4 — неверно: инвестиционные инструменты могут быть частью рационального поведения.\n5 — верно: потребитель стремится к максимальной полезности при имеющихся ограничениях.","type":"multi","q":"Выберите верные суждения о рациональном экономическом поведении и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Рациональное поведение экономического субъекта предполагает не только достаточный доход, но и разумные траты денежных средств."},{"id":"2","label":"Для всех экономических систем характерна возможность потребителей рационально вести себя в экономической деятельности."},{"id":"3","label":"Сопоставление результатов действий с затратами на их совершение не является проявлением рационального экономического поведения."},{"id":"4","label":"Рациональный потребитель не должен использовать инвестиционные инструменты."},{"id":"5","label":"Рациональное поведение позволяет извлечь максимальную пользу из потребления товаров и услуг."}],"answer":["1","2","5"],"hint":"Различайте доходы и расходы. Рациональный выбор предполагает сравнение пользы и затрат при ограниченных ресурсах.","reviewNote":"Исправлен ключ источника 15 → 125: ограниченность выбора не исключает рациональное поведение.","referenceUrl":"https://openstax.org/books/principles-economics-2e/pages/2-1-how-individuals-make-choices-based-on-their-budget-constraint"},{"id":"sc-nov12-3-q3","subject":"social","section":"course","topic":"Домохозяйства и рациональное экономическое поведение","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/0814fa89-5a2d-471f-9350-9e08f50c6613","sourceLabel":"StudyCats · Домохозяйства и рациональное экономическое поведение · База · вопрос 3","ex":"предпочтение однообразия разнообразию – выпадает: рациональный потребитель стремится к выбору, а предпочтение однообразия не является признаком рационального поведения.\nизвлечение максимальной пользы – относится: рациональный потребитель стремится извлечь максимальную пользу.\nсокращение финансовых потерь – относится: рациональный потребитель старается сократить финансовые потери.\nдействия в соответствии со своими интересами и целями – относится: рациональный потребитель действует в соответствии со своими интересами и целями.\nнаибольшая выгода – относится: рациональный потребитель стремится к наибольшей выгоде.\nминимизация выгоды при максимизации затрат – выпадает: рациональное поведение — это, наоборот, максимизация выгоды при минимизации затрат.","type":"multi","q":"Ниже приведён ряд терминов. Все они, за исключением двух, относятся к факторам, характеризующим рациональное поведение потребителя.","options":[{"id":"1","label":"предпочтение однообразия разнообразию"},{"id":"2","label":"извлечение максимальной пользы"},{"id":"3","label":"сокращение финансовых потерь"},{"id":"4","label":"действия в соответствии со своими интересами и целями"},{"id":"5","label":"наибольшая выгода"},{"id":"6","label":"минимизация выгоды при максимизации затрат"}],"answer":["1","6"],"hint":"Различайте доходы и расходы. Рациональный выбор предполагает сравнение пользы и затрат при ограниченных ресурсах."},{"id":"sc-nov12-3-q4","subject":"social","section":"course","topic":"Домохозяйства и рациональное экономическое поведение","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/0814fa89-5a2d-471f-9350-9e08f50c6613","sourceLabel":"StudyCats · Домохозяйства и рациональное экономическое поведение · База · вопрос 4","ex":"Домохозяйства выступают на рынке ресурсов как продавцы факторов производства, например труда – верно, домохозяйства продают на рынке ресурсов свой труд (а также сдают в аренду землю, предоставляют капитал) и получают за это доходы.\nИз всех участников рыночной экономики только фирмы ориентированы на получение прибыли – неверно, к получению дохода стремятся и другие участники: домохозяйства получают зарплату, ренту, проценты, а государство — доходы от госпредприятий и налоги.\nОдним из субъектов рыночных экономических отношений является государство – верно, государство — субъект рыночной экономики: оно покупает товары и услуги, устанавливает правила, собирает налоги, производит общественные блага.\nКаждый субъект рыночных экономических отношений занимается продажей природных ресурсов – неверно, субъекты рынка занимаются разной деятельностью: домохозяйства продают труд и покупают товары, фирмы производят товары и услуги.\nФирмы приобретают на рынке ресурсов факторы производства, необходимые для выпуска продукции – верно, чтобы производить товары и услуги, фирмы покупают на рынке ресурсов труд, сырьё, оборудование, арендуют землю и помещения.","type":"multi","q":"Выберите верные суждения о субъектах рыночных экономических отношений и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Домохозяйства выступают на рынке ресурсов как продавцы факторов производства, например труда."},{"id":"2","label":"Из всех участников рыночной экономики только фирмы ориентированы на получение прибыли."},{"id":"3","label":"Одним из субъектов рыночных экономических отношений является государство."},{"id":"4","label":"Каждый субъект рыночных экономических отношений занимается продажей природных ресурсов."},{"id":"5","label":"Фирмы приобретают на рынке ресурсов факторы производства, необходимые для выпуска продукции."}],"answer":["1","3","5"],"hint":"Различайте доходы и расходы. Рациональный выбор предполагает сравнение пользы и затрат при ограниченных ресурсах."},{"id":"sc-nov12-3-q5","subject":"social","section":"course","topic":"Домохозяйства и рациональное экономическое поведение","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/0814fa89-5a2d-471f-9350-9e08f50c6613","sourceLabel":"StudyCats · Домохозяйства и рациональное экономическое поведение · База · вопрос 5","ex":"Превышение расходов над доходами – неверно, если расходы превышают доходы, человек или фирма уходят в долги — это нерационально.\nУвеличение прибыли при минимизации затрат – верно, стремление получить наибольший результат при наименьших затратах — суть рационального поведения.\nАнализ собственных доходов и расходов – верно, анализ доходов и расходов позволяет разумно планировать бюджет.\nСоздание амортизационного фонда – верно, амортизационный фонд позволяет фирме заранее накопить средства на замену изношенного оборудования.\nИспользование устаревших технологий – неверно, устаревшие технологии повышают издержки и снижают эффективность.","type":"multi","q":"Найдите в приведенном списке ниже признаки рационального экономического поведения. Запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Превышение расходов над доходами"},{"id":"2","label":"Увеличение прибыли при минимизации затрат"},{"id":"3","label":"Анализ собственных доходов и расходов"},{"id":"4","label":"Создание амортизационного фонда"},{"id":"5","label":"Использование устаревших технологий"}],"answer":["2","3","4"],"hint":"Различайте доходы и расходы. Рациональный выбор предполагает сравнение пользы и затрат при ограниченных ресурсах."},{"id":"sc-nov12-3-q6","subject":"social","section":"course","topic":"Домохозяйства и рациональное экономическое поведение","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/0814fa89-5a2d-471f-9350-9e08f50c6613","sourceLabel":"StudyCats · Домохозяйства и рациональное экономическое поведение · База · вопрос 6","ex":"Рационально действующая коммерческая фирма в рыночной экономике ориентируется на максимизацию прибыли – верно, главная цель фирм в рыночной экономике — получение и максимизация прибыли.\nМодель рационального экономического поведения описывает мотивацию экономических агентов – верно, модель рационального поведения объясняет, чем руководствуются экономические субъекты: стремлением получить наибольшую выгоду при наименьших затратах.\nВ современной экономике нацеленность на клиента не влияет на увеличение прибыли – неверно, ориентация на запросы клиентов повышает спрос на товары фирмы и тем самым увеличивает её прибыль.\nЦель потребителя — извлечь максимальную полезность из потребления товаров и услуг – верно, рациональный потребитель стремится получить наибольшую пользу (полезность) от покупаемых товаров и услуг.\nРациональное поведение отказывается от сопоставления результатов действий с затратами – неверно, сопоставление результатов с затратами — основа рационального поведения.","type":"multi","q":"Выберите верные суждения о рациональном экономическом поведении и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Рационально действующая коммерческая фирма в рыночной экономике ориентируется на максимизацию прибыли."},{"id":"2","label":"Модель рационального экономического поведения описывает мотивацию экономических агентов."},{"id":"3","label":"В современной экономике нацеленность на клиента не влияет на увеличение прибыли."},{"id":"4","label":"Цель потребителя — извлечь максимальную полезность из потребления товаров и услуг."},{"id":"5","label":"Рациональное поведение отказывается от сопоставления результатов действий с затратами."}],"answer":["1","2","4"],"hint":"Различайте доходы и расходы. Рациональный выбор предполагает сравнение пользы и затрат при ограниченных ресурсах."},{"id":"sc-nov12-3-q7","subject":"social","section":"course","topic":"Домохозяйства и рациональное экономическое поведение","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/0814fa89-5a2d-471f-9350-9e08f50c6613","sourceLabel":"StudyCats · Домохозяйства и рациональное экономическое поведение · База · вопрос 7","ex":"Доходы домохозяйства - это сумма полученных денежных средств за определённый период.\n\nРасходы домохозяйства - это сумма средств, направленных на собственные нужды.\n\nА)  проценты по вкладам - 1)  доходная часть, это доход, который получает владелец вклада от банка.\n\nБ)  заработная плата - 1)  доходная часть, это доход, который получает работник от работодателя.\n\nВ)  оплата коммунальных услуг - 2)  расходная часть, это расход, который несет человек или семья за жилищно-коммунальные услуги.\n\nГ)  дивиденды по акциям - 1)  доходная часть, это доход, который получает акционер от компании.\n\nД)  страховые взносы - 2)  расходная часть, это расход, который человек или компания платит страховой компании за страховку.","type":"match","q":"Установите соответствие между примерами и составными частями бюджета домохозяйства: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\n\nПРИМЕР","options":["доходная часть","расходная часть"],"rows":[{"id":"row1","label":"проценты по вкладам","answer":"доходная часть"},{"id":"row2","label":"заработная плата","answer":"доходная часть"},{"id":"row3","label":"оплата коммунальных услуг","answer":"расходная часть"},{"id":"row4","label":"дивиденды по акциям","answer":"доходная часть"},{"id":"row5","label":"страховые взносы","answer":"расходная часть"}],"hint":"Определите, что описывает каждый пункт: вид заработной платы или доходную и расходную части бюджета."},{"id":"sc-nov12-3-q8","subject":"social","section":"course","topic":"Домохозяйства и рациональное экономическое поведение","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/0814fa89-5a2d-471f-9350-9e08f50c6613","sourceLabel":"StudyCats · Домохозяйства и рациональное экономическое поведение · База · вопрос 8","ex":"Одним из действий потребителя является оценка возможных вариантов покупки – верно, рациональный потребитель сравнивает варианты покупки, прежде чем сделать выбор.\nДействия потребителя являются взвешенными с его точки зрения по поводу полезности товара – верно, рациональный потребитель взвешивает, насколько товар ему полезен.\nСпрос потребителя на товары зависит первостепенно от того, какие товары покупают окружающие его люди – неверно, спрос рационального потребителя зависит прежде всего от его потребностей, дохода и цен, а не от того, что покупают окружающие.\nПри рациональном выборе благ возможности потребителя не ограничены ценами благ и его доходом – неверно, выбор потребителя всегда ограничен его доходом и ценами товаров.\nРациональным поведением потребителя считается продуманное поведение, предполагающее сопоставление результатов действия с затратами – верно, это определение рационального поведения потребителя.","type":"multi","q":"Выберите верные суждения об отличительных чертах рационального поведения потребителя.","options":[{"id":"1","label":"Одним из действий потребителя является оценка возможных вариантов покупки."},{"id":"2","label":"Действия потребителя являются взвешенными с его точки зрения по поводу полезности товара."},{"id":"3","label":"Спрос потребителя на товары зависит первостепенно от того, какие товары покупают окружающие его люди."},{"id":"4","label":"При рациональном выборе благ возможности потребителя не ограничены ценами благ и его доходом."},{"id":"5","label":"Рациональным поведением потребителя считается продуманное поведение, предполагающее сопоставление результатов действия с затратами."}],"answer":["1","2","5"],"hint":"Различайте доходы и расходы. Рациональный выбор предполагает сравнение пользы и затрат при ограниченных ресурсах."},{"id":"sc-nov12-3-q9","subject":"social","section":"course","topic":"Домохозяйства и рациональное экономическое поведение","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/0814fa89-5a2d-471f-9350-9e08f50c6613","sourceLabel":"StudyCats · Домохозяйства и рациональное экономическое поведение · База · вопрос 9","ex":"дивиденды – доход: дивиденды — часть прибыли компании, которую получает владелец акций.\nвыплата кредита и процентов по нему – не доход, а расход: возврат кредита и уплата процентов банку.\nстраховые выплаты – доход: страховые выплаты он получит от страховой компании при наступлении страхового случая.\nземельный налог – не доход, а расход: обязательный платёж за владение земельным участком.\nстраховые взносы – не доход, а расход: плата страховой компании за договор страхования.\nприбыль автомастерской – доход: прибыль от предпринимательской деятельности — работы автомастерской.","type":"multi","q":"Станислав Николаевич владеет автомастерской. Одну часть своих сбережений он вложил в акции крупных компаний, другую потратил на оформление договора страхования имущества. Станислав Николаевич также взял кредит и купил земельный участок. Что из перечисленного может относиться к доходам Станислава Николаевича? Запишите цифры, под которыми указаны доходы.","options":[{"id":"1","label":"дивиденды"},{"id":"2","label":"выплата кредита и процентов по нему"},{"id":"3","label":"страховые выплаты"},{"id":"4","label":"земельный налог"},{"id":"5","label":"страховые взносы"},{"id":"6","label":"прибыль автомастерской"}],"answer":["1","3","6"],"hint":"Различайте доходы и расходы. Рациональный выбор предполагает сравнение пользы и затрат при ограниченных ресурсах."},{"id":"sc-nov12-3-q10","subject":"social","section":"course","topic":"Домохозяйства и рациональное экономическое поведение","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/0814fa89-5a2d-471f-9350-9e08f50c6613","sourceLabel":"StudyCats · Домохозяйства и рациональное экономическое поведение · База · вопрос 10","ex":"Доля тех, кто стал реже ходить в магазин, уменьшилась за год – верно: доля тех, кто стал реже ходить в магазин, в 2015 г. меньше, чем в 2014 г.\nДоля тех, кто стал покупать более дешёвые продукты, увеличилась за год – верно: доля тех, кто стал покупать более дешёвые продукты, выросла.\nСреди опрошенных в 2015 г. доля тех, кто отказался от покупки некоторых продуктов, больше доли тех, кто считал, что кризис не повлиял на их потребительское поведение – верно: в 2015 г. отказавшихся от некоторых продуктов больше, чем тех, на кого кризис не повлиял.\nРавные доли респондентов в обоих опросах отметили, что кризис не повлиял на их потребительское поведение – неверно: доли тех, на кого кризис не повлиял, в двух опросах разные.\nСреди опрошенных в 2014 г. доля тех, кто стал реже ходить в магазин, меньше доли тех, кто стал покупать более дешёвые продукты – неверно: в 2014 г. доля тех, кто стал реже ходить в магазин, не меньше доли тех, кто стал покупать более дешёвые продукты.","type":"multi","q":"Учёные изучали потребительское поведение жителей страны Z в условиях экономического кризиса. На гистограмме приведены данные (в % от числа отвечавших) о том, как в течение года изменилось потребительское поведение. Найдите в приведённом списке выводы, которые можно сделать на основе диаграммы, и запишите цифры, под которыми они указаны","options":[{"id":"1","label":"Доля тех, кто стал реже ходить в магазин, уменьшилась за год."},{"id":"2","label":"Доля тех, кто стал покупать более дешёвые продукты, увеличилась за год."},{"id":"3","label":"Среди опрошенных в 2015 г. доля тех, кто отказался от покупки некоторых продуктов, больше доли тех, кто считал, что кризис не повлиял на их потребительское поведение."},{"id":"4","label":"Равные доли респондентов в обоих опросах отметили, что кризис не повлиял на их потребительское поведение."},{"id":"5","label":"Среди опрошенных в 2014 г. доля тех, кто стал реже ходить в магазин, меньше доли тех, кто стал покупать более дешёвые продукты."}],"answer":["1","2","3"],"hint":"Сравнивайте значения на диаграмме, обращая внимание на группы, годы и единицы измерения.","bodyHtml":"<p>Диаграмма к заданию: <a href=\"https://cdn.studycats.ru/NhFQ8kUKRLMZ_1.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения</a></p><p>Если изображение недоступно, пропустите задание: для ответа нужна диаграмма из источника.</p>"},{"id":"sc-nov12-3-q11","subject":"social","section":"course","topic":"Домохозяйства и рациональное экономическое поведение","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/0814fa89-5a2d-471f-9350-9e08f50c6613","sourceLabel":"StudyCats · Домохозяйства и рациональное экономическое поведение · База · вопрос 11","ex":"1 — заработная плата за работу администратором.\n2 — пенсия бабушки не является доходом Данчук; наследование дачи не означает наследование пенсии.\n3 — в условии не указано получение социальных выплат.\n4 — плата за сдачу дачи в аренду относится к доходам от собственности.\n5 — акции могут приносить дивиденды.\n6 — одного упоминания о сыне недостаточно, чтобы установить получение материнского капитала. В условии таких сведений нет.","type":"multi","q":"Гражданка Данчук работает администратором в салоне красоты. Каждое лето она сдаёт в аренду дачу, которую получила в наследство от бабушки. Несколько лет тому назад она приобрела акции нефтеперерабатывающего завода. У гражданки Данчук растёт сын. На основании только приведённых сведений выберите в списке источники доходов гражданки Данчук и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"заработная плата администратора салона"},{"id":"2","label":"пенсия бабушки"},{"id":"3","label":"социальные выплаты"},{"id":"4","label":"рента"},{"id":"5","label":"доход от ценных бумаг"},{"id":"6","label":"материнский капитал"}],"answer":["1","4","5"],"hint":"Различайте доходы и расходы. Рациональный выбор предполагает сравнение пользы и затрат при ограниченных ресурсах.","reviewNote":"Уточнено условие и исправлен ключ источника 1456 → 145: не добавляем доход, получение которого не установлено."},{"id":"sc-nov12-3-q12","subject":"social","section":"course","topic":"Домохозяйства и рациональное экономическое поведение","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/0814fa89-5a2d-471f-9350-9e08f50c6613","sourceLabel":"StudyCats · Домохозяйства и рациональное экономическое поведение · База · вопрос 12","ex":"Модель рационального экономического поведения описывает поведение только такого субъекта рыночных экономических отношений, как фирма. – неверно, модель рационального поведения описывает действия всех экономических субъектов: и домохозяйств, и фирм.\nРациональное поведение субъектов рыночных экономических отношений основано на сопоставлении результатов действий с затратами. – верно, сопоставление выгод и затрат — это суть рационального экономического выбора для любого субъекта (потребителя, фирмы).\nРациональное экономическое поведение – это модель принятия экономических решений, которая предполагает минимизацию затрат без учета иных факторов – неверно, рациональное поведение предполагает достижение максимального результата при данных затратах, но всегда с учетом множества других факторов (рисков, будущих выгод, альтернативных издержек).\nДомохозяйства являются субъектами рынка, могут участвовать в рыночных отношениях. – верно, домохозяйства — ключевые субъекты рынка, выступающие в роли потребителей и поставщиков ресурсов.\nДомохозяйства действуют на рынке потребительских товаров и услуг. – верно, основная экономическая роль домохозяйств — потребление товаров и услуг на соответствующем рынке.","type":"multi","q":"Выберите верные суждения о субъектах экономических отношений и рациональном поведении и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Модель рационального экономического поведения описывает поведение только такого субъекта рыночных экономических отношений, как фирма."},{"id":"2","label":"Рациональное поведение субъектов рыночных экономических отношений основано на сопоставлении результатов действий с затратами."},{"id":"3","label":"Рациональное экономическое поведение – это модель принятия экономических решений, которая предполагает минимизацию затрат без учета иных факторов"},{"id":"4","label":"Домохозяйства являются субъектами рынка, могут участвовать в рыночных отношениях."},{"id":"5","label":"Домохозяйства действуют на рынке потребительских товаров и услуг."}],"answer":["2","4","5"],"hint":"Различайте доходы и расходы. Рациональный выбор предполагает сравнение пользы и затрат при ограниченных ресурсах."},{"id":"sc-nov12-3-q13","subject":"social","section":"course","topic":"Домохозяйства и рациональное экономическое поведение","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/0814fa89-5a2d-471f-9350-9e08f50c6613","sourceLabel":"StudyCats · Домохозяйства и рациональное экономическое поведение · База · вопрос 13","ex":"Экономическая функция домохозяйства состоит в обеспечении нормальных условий жизни. – верно, создание и поддержание нормальных условий жизни для своих членов — основная социально-экономическая функция домохозяйства.\nВ домохозяйство могут входить люди, не имеющие кровной связи друг с другом. – верно, домохозяйство определяется как группа людей, проживающих вместе и ведущих общее хозяйство, что не обязательно подразумевает родственные связи.\nДомохозяйства могут только поставлять ресурсы на рынок. – неверно, домохозяйства не только поставляют ресурсы, но и выступают на рынке в качестве потребителей товаров и услуг.\nДомохозяйства в настоящее время в основном выполняют функцию потребительскую. – верно, основной экономической ролью домохозяйства в рыночной экономике является потребление товаров и услуг.\nОтличие домохозяйства от семьи в том, что у домохозяйства есть общий бюджет и место проживания. – неверно, и семья, и домохозяйство имеют общий бюджет и место проживания. Ключевое отличие в том, что домохозяйство может включать не родственников, а семья основана на родственных или супружеских отношениях.","type":"multi","q":"Выберите верные суждения о домохозяйствах и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Экономическая функция домохозяйства состоит в обеспечении нормальных условий жизни."},{"id":"2","label":"В домохозяйство могут входить люди, не имеющие кровной связи друг с другом."},{"id":"3","label":"Домохозяйства могут только поставлять ресурсы на рынок."},{"id":"4","label":"Домохозяйства в настоящее время в основном выполняют функцию потребительскую."},{"id":"5","label":"Отличие домохозяйства от семьи в том, что у домохозяйства есть общий бюджет и место проживания."}],"answer":["1","2","4"],"hint":"Различайте доходы и расходы. Рациональный выбор предполагает сравнение пользы и затрат при ограниченных ресурсах."},{"id":"sc-nov12-3-q14","subject":"social","section":"course","topic":"Домохозяйства и рациональное экономическое поведение","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/0814fa89-5a2d-471f-9350-9e08f50c6613","sourceLabel":"StudyCats · Домохозяйства и рациональное экономическое поведение · База · вопрос 14","ex":"Рациональное экономическое поведение – это получение максимально возможной пользы при минимальных затратах – верно, это классическое определение рационального экономического поведения.\nРациональное экономическое поведение потребителя выражается в приобретении товаров высокого качества – неверно, рациональный потребитель ищет оптимальное соотношение цены и полезности, а не обязательно самые качественные (и дорогие) товары.\nРациональное экономическое поведение – это теоретическое представление о поведении экономического субъекта, которое удовлетворяет определённым условиям – верно, рациональное поведение — теоретическая модель поведения экономического субъекта, которая предполагает определённые условия (свобода выбора, информированность, сравнение выгод и затрат).\nРациональное поведение потребителя - это продуманное поведение, предполагающее сопоставление результатов действий с затратами - верно, прежде чем что-то купить, рациональный потребитель взвешивает, какую пользу принесёт покупка и сколько она будет стоить, и выбирает вариант с наилучшим соотношением выгоды и затрат.\nРациональное экономическое поведение производителя заключается в производстве максимального объёма продукции – неверно, рациональный производитель стремится не к максимальному объёму выпуска, а к максимальной прибыли.","type":"multi","q":"Выберите верные суждения о рациональном экономическом поведении и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Рациональное экономическое поведение – это получение максимально возможной пользы при минимальных затратах."},{"id":"2","label":"Рациональное экономическое поведение потребителя выражается в приобретении товаров высокого качества."},{"id":"3","label":"Рациональное экономическое поведение – это теоретическое представление о поведении экономического субъекта, которое удовлетворяет определённым условиям."},{"id":"4","label":"Рациональное поведение потребителя - это продуманное поведение, предполагающее сопоставление результатов действий с затратами"},{"id":"5","label":"Рациональное экономическое поведение производителя заключается в производстве максимального объёма продукции."}],"answer":["1","3","4"],"hint":"Различайте доходы и расходы. Рациональный выбор предполагает сравнение пользы и затрат при ограниченных ресурсах."},{"id":"sc-nov12-3-q15","subject":"social","section":"course","topic":"Домохозяйства и рациональное экономическое поведение","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/0814fa89-5a2d-471f-9350-9e08f50c6613","sourceLabel":"StudyCats · Домохозяйства и рациональное экономическое поведение · База · вопрос 15","ex":"Учёба дочери в гимназии – не доход, а расход: обучение в гимназии требует трат.\nДенежные подарки от близких родственников на праздники – доход: денежные подарки увеличивают бюджет семьи.\nОтдых в Турции каждый год – не доход, а расход: семья тратит деньги на отдых.\nДивиденды по акциям – доход: дивиденды — часть прибыли компании, которую получает владелец акций.\nВыплата транспортного налога за машину, принадлежавшую отцу – не доход, а расход: обязательный платёж за владение автомобилем.\nЗаработная плата отца и матери – доход: основной источник дохода семьи — заработная плата.","type":"multi","q":"Семья Потаповых состоит из отца, матери и 14-летней дочери. Они участвовали в опросе, где просматривалась доходная и расходная части их бюджета. Найдите в приведённом ниже списке примеры доходов семьи и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Учёба дочери в гимназии"},{"id":"2","label":"Денежные подарки от близких родственников на праздники"},{"id":"3","label":"Отдых в Турции каждый год"},{"id":"4","label":"Дивиденды по акциям"},{"id":"5","label":"Выплата транспортного налога за машину, принадлежавшую отцу"},{"id":"6","label":"Заработная плата отца и матери"}],"answer":["2","4","6"],"hint":"Различайте доходы и расходы. Рациональный выбор предполагает сравнение пользы и затрат при ограниченных ресурсах."}]}];for(const t of incoming){if(!window.EGE_TESTS.some(x=>x.id===t.id))window.EGE_TESTS.push(t);}Object.assign(window.EGE_VIDEO_LESSONS.byTest,{"social-course-nov12-1":[{"url":"https://rutube.ru/play/embed/ae448b5907b180ebb43387936b4d085c/?p=AEFhzHZ-AHgi4IqFcCLIgA","title":"Рынок труда. Безработица"}],"social-course-nov12-2":[{"url":"https://rutube.ru/play/embed/ae448b5907b180ebb43387936b4d085c/?p=AEFhzHZ-AHgi4IqFcCLIgA","title":"Рынок труда. Безработица"}],"social-course-nov12-3":[{"url":"https://rutube.ru/play/embed/d84e4e0b91e5bfc39b4d4f57872ec3a3/?p=NRCdIjKokwoG12-FoE0D-w","title":"Домохозяйства и рациональное экономическое поведение"}]});})();
